def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []

    # Find each 4-connected nonzero object.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == color and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            top = min(y for y, x in cells)
            bottom = max(y for y, x in cells)
            left = min(x for y, x in cells)
            right = max(x for y, x in cells)

            # Detect an enclosed zero region inside the object's bounding box.
            outside = set()
            stack = []
            for y in range(top, bottom + 1):
                for x in range(left, right + 1):
                    if (y in (top, bottom) or x in (left, right)) and grid[y][x] == 0:
                        outside.add((y, x))
                        stack.append((y, x))
            while stack:
                y, x = stack.pop()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (top <= ny <= bottom and left <= nx <= right and
                            grid[ny][nx] == 0 and (ny, nx) not in outside):
                        outside.add((ny, nx))
                        stack.append((ny, nx))
            has_hole = any(
                grid[y][x] == 0 and (y, x) not in outside
                for y in range(top, bottom + 1)
                for x in range(left, right + 1)
            )
            objects.append({
                "cells": cells, "top": top, "bottom": bottom,
                "left": left, "right": right, "hole": has_hole
            })

    placed = []
    # Enclosed shapes pack upward; other shapes pack downward.
    for hole, upward in ((True, True), (False, False)):
        group = [o for o in objects if o["hole"] == hole]
        group.sort(key=lambda o: o["top"] if upward else -o["bottom"])
        for o in group:
            height = o["bottom"] - o["top"] + 1
            y = 0 if upward else h - height
            step = 1 if upward else -1
            while 0 <= y and y + height <= h:
                collision = any(
                    not (o["right"] < p["left"] or o["left"] > p["right"] or
                         y + height - 1 < p["y"] or y > p["y"] + p["height"] - 1)
                    for p in placed
                )
                if not collision:
                    break
                y += step
            placed.append({
                "obj": o, "y": y, "height": height,
                "left": o["left"], "right": o["right"]
            })

    out = [[0] * w for _ in range(h)]
    for p in placed:
        o = p["obj"]
        dy = p["y"] - o["top"]
        for y, x in o["cells"]:
            out[y + dy][x] = grid[y][x]
    return out
